package com.inventra.backend.service; import com.inventra.backend.dto.InventoryResponse; import com.inventra.backend.model.*; import com.inventra.backend.repository.ReservationRepository; import org.springframework.stereotype.Service; import java.util.*; @Service public class ReservationService { private final ReservationRepository repo; private final InventoryCoreService inv; public ReservationService(ReservationRepository r,InventoryCoreService i){repo=r;inv=i;} public List<StockReservation> byOrder(String id){return repo.findByOrderId(id);} public InventoryResponse reserve(String wid,String pid,int q,String ref){InventoryResponse x=inv.reserve(wid,pid,q,ref);StockReservation s=new StockReservation();s.setOrderId(ref);s.setWarehouseId(wid);s.setProductId(pid);s.setQuantity(q);repo.save(s);return x;} }
